using namespace std;



typedef long long ll;

typedef unsigned long long ull;

typedef pair<ll, ll> P;

typedef pair<ll, P> PP;



ll N;

vector<ll> h;



ll memo[100001];



ll func(ll pos)

{

	if (memo[pos] != -1) return memo[pos];



	if (pos == 0) return 0;

	if (pos == 1) return abs(h[1] - h[0]);



	memo[pos] = min(func(pos - 1) + abs(h[pos-1] - h[pos]), func(pos - 2) + abs(h[pos - 2] - h[pos]));



	return memo[pos];

}



int main()

{

	cin.tie(0);

	ios::sync_with_stdio(false);



	cin >> N;

	h.resize(N);



	for (ll i = 0; i < N; ++i) cin >> h[i];

	for (auto& e : memo) e = -1;



	cout << func(N - 1) << endl;



	//system("pause");

}

